        uint256 baseOut = 0;
        uint256 quoteOut = 0;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 baseAmount, uint256 quoteAmount) {
            reverted = false;
            baseOut = baseAmount;
            quoteOut = quoteAmount;
        } catch {
            reverted = true;
        }
        uint256 afterShares;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterShares = __r; } catch { return; }
        uint256 baseReserveAfter;
        uint256 quoteReserveAfter;
        try c.getVaultReserve() returns (uint256 __r0, uint256 __r1) { baseReserveAfter = __r0; quoteReserveAfter = __r1; } catch { return; }
