        try c.totalSupply() returns (uint256 __r) { totalAfter = __r; } catch { return; }
        assertTrue(reverted || (
                // caller had enough shares to sell
                beforeShares >= shareAmount
                // shares decreased by exactly shareAmount
                && (beforeShares - afterShares == shareAmount)
                // totalSupply decreased accordingly
                && (totalBefore - totalAfter == shareAmount)
                // reserves account for the amounts paid out (no more tokens disappeared than reported)
                && (baseReserveAfter + baseOut <= baseReserveBefore)
                && (quoteReserveAfter + quoteOut <= quoteReserveBefore)
            ));
    }

    function testFuzz_run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes memory data, uint256 deadline) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
